/// **Key idea**: Use a higher-ranked trait bound (HRTB) so that the closure
/// can borrow `&mut workspace` and `&crate_name` for the duration of the
/// async future without lifetime conflicts.
///
/// By writing `for<'a> F: FnOnce(&'a mut Workspace<...>, &'a str) -> ... + 'a`,
/// we allow the compiler to see that "for any lifetime `'a`",
/// the closure returns a future that *only* needs `'a` to remain valid.
/// This avoids the "`'1` must outlive `'2`" error when returning the pinned future.
#[tracing::instrument(level = "trace", skip(operation))]
pub async fn run_with_workspace_and_crate_name<R, F>(user_supplied_path: Option<PathBuf>, skip_git_check: bool, crate_name: String, operation: F) -> Result<R, WorkspaceError> where
    // The closure's result
    R: Send + 'static,

    // We define a higher-ranked trait bound over `'a`. This says:
    // "For any lifetime `'a`, the closure can accept
    //  `&'a mut Workspace` and `&'a str`, returning a Future
    //  that also does not outlive `'a`."
    //
    // This is crucial to allow the closure to borrow `workspace` and `crate_name`
    // for the async block without requiring `'static` references.
    F: for<'a> FnOnce(
            &'a mut Workspace<PathBuf, CrateHandle>,
            &'a str,
        ) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<R, WorkspaceError>> + Send + 'a>>
      + Send
      + 'static,


/// This new helper function `run_with_crate` parallels the existing
/// `run_with_workspace` pattern but focuses on a single crate. It:
///
/// 1) Builds a `CrateHandle` from the given `PathBuf`.
/// 2) Optionally checks Git cleanliness or other invariants (if desired).
/// 3) Hands the handle to the user-provided closure.
/// 4) Optionally re-validates the crate afterward.
/// We define it in full below:
#[tracing::instrument(level="trace", skip(operation))]
pub async fn run_with_crate<R, F>(crate_path: PathBuf, skip_git_check: bool, operation: F) -> Result<R, WorkspaceError> where
    // The closure's eventual result:
    R: Send + 'static,

    // Our closure (operation) must accept `&CrateHandle` and return
    // a `Future<Output=Result<R, WorkspaceError>>`.
    F: for<'a> FnOnce(
            &'a mut CrateHandle,
        ) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<R, WorkspaceError>> + Send + 'a>>
      + Send
      + 'static, {
    // 1) Create the CrateHandle from `crate_path`
    debug!("Creating CrateHandle from path='{}'", crate_path.display());
    let mut handle = CrateHandle::new(&crate_path).await.map_err(|crate_err| {
        error!(
            "Could not create CrateHandle from '{}': {:?}",
            crate_path.display(),
            crate_err
        );
        WorkspaceError::CrateError(crate_err)
    })?;

    // 2) (Optional) If you want to ensure Git is clean for single crates, you'd do so here.
    //    We might skip it or do something akin to:
    if !skip_git_check {
        // You could do something like `handle.ensure_git_clean()?` if that were in your API.
        debug!("(Skipping or not) any single-crate-level Git checks as needed.");
    }

    // 3) Hand control off to the user-provided closure.
    info!(
        "Running single-crate operation for crate path='{}'...",
        crate_path.display()
    );
    let result = {
        let future = operation(&mut handle);
        future.await?
    };

    // 4) Optionally validate integrity after the operation
    //    (similar to how `run_with_workspace` does `workspace.validate_integrity()`).
    info!("Validating crate integrity post-operation...");
    handle.validate_integrity().await.map_err(|err| {
        error!("Crate integrity validation failed: {:?}", err);
        WorkspaceError::CrateError(err)
    })?;
    debug!("Crate integrity is valid. Done.");

    // 5) Return whatever the closure returned
    Ok(result)
}


/// This function handles the `lock-versions` logic:
pub async fn get_lock_versions_flow(workspace_path: Option<PathBuf>, skip_git_check: bool) -> Result<(), WorkspaceError> {
    // We can re-use your run_with_workspace(...) helper if you want to
    // ensure we have a valid workspace, do Git checks, etc.
    run_with_workspace(workspace_path, skip_git_check, |ws| {
        Box::pin(async move {
            let root_dir = ws.as_ref();  // the workspace root path

            // Now call our library code
            let lock_map = build_lock_versions(&root_dir)
                .await
                .map_err(|crate_err| {
                    error!("Failed to read or parse Cargo.lock: {:?}", crate_err);
                    // Convert `CrateError` => `WorkspaceError`
                    WorkspaceError::CrateError(crate_err)
                })?;

            // Print the results in some human-friendly way:
            info!("Lockfile contains {} distinct crates:", lock_map.len());
            for (crate_name, versions) in &lock_map {
                debug!("   - {} => versions: {:?}", crate_name, versions);
                // or do a more polished print:
                println!("{} => {:?}", crate_name, versions);
            }

            Ok(())
        })
    }).await
}


/// 2) We define a new helper function that is basically the same pattern as
///    `run_with_workspace_and_crate_name`, but it takes *two* crate name strings.
///    This avoids the lifetime conflict by using a higher-ranked trait bound.
#[tracing::instrument(level = "trace", skip(operation))]
pub async fn run_with_workspace_and_two_crate_names<R, F>(user_supplied_path: Option<PathBuf>, skip_git_check: bool, target_crate_name: String, dep_crate_name: String, operation: F) -> Result<R, WorkspaceError> where
    R: Send + 'static,
    F: for<'a> FnOnce(
            &'a mut Workspace<PathBuf, CrateHandle>,
            &'a str,  // target crate name
            &'a str,  // dep crate name
        ) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<R, WorkspaceError>> + Send + 'a>>
      + Send
      + 'static, {
    // 1) Determine the workspace directory
    let workspace_path = match user_supplied_path {
        Some(path) => {
            debug!("User supplied a workspace path='{}'", path.display());
            path
        }
        None => {
            debug!("No workspace path supplied; falling back to current directory");
            std::env::current_dir().map_err(|io_err| {
                error!("Could not get current_dir: {:?}", io_err);
                WorkspaceError::IoError {
                    io_error: std::sync::Arc::new(io_err),
                    context: "getting current_dir in run_with_workspace_and_two_crate_names".to_string(),
                }
            })?
        }
    };

    // 2) Load/create the workspace
    info!("Opening workspace at '{}'", workspace_path.display());
    let mut workspace = Workspace::<PathBuf, CrateHandle>::new(&workspace_path).await.map_err(|e| {
        error!("Failed to create/load workspace: {:?}", e);
        e
    })?;

    // 3) Optionally check Git cleanliness
    if !skip_git_check {
        info!("Ensuring Git working directory is clean...");
        workspace.ensure_git_clean().await.map_err(|git_err| {
            error!("Git is not clean: {:?}", git_err);
            WorkspaceError::GitError(git_err)
        })?;
        debug!("Git working directory confirmed clean.");
    } else {
        debug!("Skipping Git clean check because `skip_git_check` is true.");
    }

    // 4) Hand control off to the subcommand's closure
    info!(
        "Running subcommand-specific logic for target='{}' / dep='{}' ...",
        target_crate_name, dep_crate_name
    );

    // We call `operation(...)` right here and `.await` immediately.
    let result = {
        let future = operation(&mut workspace, &target_crate_name, &dep_crate_name);
        future.await?
    };

    // 5) Validate workspace integrity afterward
    info!("Validating workspace integrity post-operation...");
    workspace.validate_integrity().await.map_err(|err| {
        error!("Workspace integrity validation failed: {:?}", err);
        err
    })?;
    debug!("Workspace integrity is valid. Done.");

    info!(
        "Successfully completed subcommand: target='{}', dep='{}' in workspace='{}'",
        target_crate_name, dep_crate_name, workspace_path.display()
    );

    // 6) Return whatever the closure's operation returned
    Ok(result)
}


/// This function handles the `ws get toml --section <SECTION> [--crate <NAME>]` logic:
///
/// - If `crate_name` is `Some(...)`, we load that crate’s `Cargo.toml` and attempt
///   to retrieve the specified `<SECTION>` from it, printing the result.
/// - If `crate_name` is `None`, we load the *workspace’s root* `Cargo.toml`
///   (i.e., `<workspace_root>/Cargo.toml`) and retrieve the specified `<SECTION>`.
#[tracing::instrument(level = "trace", skip(section, crate_name))]
pub async fn get_toml_section_flow(section: String, crate_name: Option<String>) -> Result<(), WorkspaceError> {
    // We'll reuse `run_with_workspace(...)` so we load the workspace from the current dir
    // (or whichever default logic that function provides).
    // We won't do a Git check here, to keep it simple. If you want a Git check, adapt as needed.
    run_with_workspace(None, false, move |ws| {
        Box::pin(async move {
            match crate_name {
                Some(ref name) => {
                    info!("Fetching TOML section='{}' for crate='{}' ...", section, name);

                    // 1) Attempt to find the crate by name
                    let arc_crate = ws.find_crate_by_name(name).await.ok_or_else(|| {
                        error!("No crate named '{}' found in workspace for 'get toml' subcommand", name);
                        CrateError::CrateNotFoundInWorkspace {
                            crate_name: name.to_owned(),
                        }
                    })?;

                    // 2) Lock to retrieve the CargoToml handle (or parse it as needed)
                    let handle = arc_crate.lock().await.clone();
                    let cargo_toml = handle.cargo_toml();

                    let guard = cargo_toml.lock().await;

                    // 3) Attempt to retrieve the specified `section` from `cargo_toml.content()`
                    let top_level = guard.get_content();

                    if let Some(value) = top_level.get(&section) {
                        // We’ll pretty-print this chunk
                        let rendered = toml::to_string_pretty(value)?;
                        println!("[{section}] in crate='{name}':\n{}", rendered);
                    } else {
                        warn!(
                            "Section '{}' not found in Cargo.toml for crate='{}'. Printing top-level content instead.",
                            section, name
                        );
                        // Optional fallback: just show entire top-level if user wants
                        let entire = toml::to_string_pretty(top_level)?;
                        println!("No section named '{}'. Full Cargo.toml:\n{}", section, entire);
                    }
                }
                None => {
                    info!("Fetching TOML section='{}' from the WORKSPACE root Cargo.toml ...", section);

                    // 1) We assume that `<workspace_root>/Cargo.toml` is the top-level
                    let workspace_root = ws.as_ref();
                    let root_cargo_toml_path = workspace_root.join("Cargo.toml");

                    // 2) Parse or load that file
                    debug!("Reading root Cargo.toml at: {:?}", root_cargo_toml_path);
                    if !root_cargo_toml_path.exists() {
                        error!("No Cargo.toml at workspace root. Searched: {:?}", root_cargo_toml_path);
                        return Err(WorkspaceError::IoError {
                            io_error: Arc::new(std::io::Error::new(
                                std::io::ErrorKind::NotFound,
                                "workspace root Cargo.toml not found",
                            )),
                            context: format!("Missing file at {:?}", root_cargo_toml_path),
                        });
                    }
                    let root_handle = CargoToml::new_sync(&root_cargo_toml_path)?;

                    // 3) Retrieve the specified `section` from the root’s top-level TOML
                    let top_level = root_handle.content();
                    if let Some(value) = top_level.get(&section) {
                        let rendered = toml::to_string_pretty(value)?;
                        println!("[{section}] in workspace root Cargo.toml:\n{}", rendered);
                    } else {
                        warn!(
                            "Section '{}' not found in the workspace root Cargo.toml. Printing full contents instead.",
                            section
                        );
                        let entire = toml::to_string_pretty(top_level)?;
                        println!("No section named '{}'. Full Cargo.toml:\n{}", section, entire);
                    }
                }
            }
            Ok(())
        })
    })
    .await
}


/// This helper is analogous to `run_with_workspace_and_crate_name`, but it only loads
/// the workspace (optionally checking Git). No crate name needed.
#[tracing::instrument(level = "trace", skip(operation))]
pub async fn run_with_workspace<R, F>(user_supplied_path: Option<PathBuf>, skip_git_check: bool, operation: F) -> Result<R, WorkspaceError> where
    R: Send + 'static,
    F: for<'a> FnOnce(
            &'a mut Workspace<PathBuf, CrateHandle>,
        ) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<R, WorkspaceError>> + Send + 'a>>
      + Send
      + 'static, {
    // 1) Determine the workspace directory
    let workspace_path = match user_supplied_path {
        Some(path) => {
            debug!("User supplied a workspace path='{}'", path.display());
            path
        }
        None => {
            debug!("No workspace path supplied; using current directory");
            std::env::current_dir().map_err(|io_err| {
                error!("Could not get current_dir: {:?}", io_err);
                WorkspaceError::IoError {
                    io_error: Arc::new(io_err),
                    context: "getting current_dir in run_with_workspace".to_string(),
                }
            })?
        }
    };

    // 2) Load the workspace
    info!("Opening workspace at '{}'", workspace_path.display());
    let mut workspace = Workspace::<PathBuf, CrateHandle>::new(&workspace_path).await.map_err(|e| {
        error!("Failed to open workspace: {:?}", e);
        e
    })?;

    // 3) Optionally check Git
    if !skip_git_check {
        info!("Ensuring Git working directory is clean...");
        workspace.ensure_git_clean().await.map_err(|git_err| {
            error!("Git is not clean: {:?}", git_err);
            WorkspaceError::GitError(git_err)
        })?;
    } else {
        debug!("Skipping git check because skip_git_check=true");
    }

    // 4) Run the closure immediately
    let result = {
        let fut = operation(&mut workspace);
        fut.await?
    };

    // 5) Validate integrity
    info!("Validating workspace integrity post-operation...");
    workspace.validate_integrity().await?;

    info!("Done analyzing or operating on the workspace at '{}'", workspace_path.display());
    Ok(result)
}

